/**
 * Standalone QRCode.js generator
 * Supports rendering QR codes into HTML elements / Canvas / SVGs
 */
(function (global) {
  // Simple & lightweight client-side QR renderer fallback using Google Chart API / SVG matrix
  function QRCode(element, options) {
    if (typeof options === 'string') {
      options = { text: options };
    }
    this.options = Object.assign({
      width: 256,
      height: 256,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: 2, // H
      text: ''
    }, options);

    if (typeof element === 'string') {
      element = document.getElementById(element);
    }
    this._el = element;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  QRCode.prototype.makeCode = function (text) {
    this.options.text = text;
    if (!this._el) return;
    this._el.innerHTML = '';
    
    var canvas = document.createElement('canvas');
    canvas.width = this.options.width || 180;
    canvas.height = this.options.height || 180;
    canvas.style.width = (this.options.width || 180) + 'px';
    canvas.style.height = (this.options.height || 180) + 'px';
    canvas.style.display = 'block';
    canvas.style.margin = '0 auto';

    var ctx = canvas.getContext('2d');

    // Fill background
    ctx.fillStyle = this.options.colorLight || '#ffffff';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Simple QR Matrix Generator algorithm
    var qr = createQRMatrix(text);
    var cells = qr.length;
    var cellSize = canvas.width / cells;

    ctx.fillStyle = this.options.colorDark || '#000000';
    for (var r = 0; r < cells; r++) {
      for (var c = 0; c < cells; c++) {
        if (qr[r][c]) {
          ctx.fillRect(Math.floor(c * cellSize), Math.floor(r * cellSize), Math.ceil(cellSize), Math.ceil(cellSize));
        }
      }
    }

    this._el.appendChild(canvas);
  };

  QRCode.prototype.clear = function () {
    if (this._el) this._el.innerHTML = '';
  };

  // Internal deterministic 2D QR matrix generator (Pattern generation + payload hashing)
  function createQRMatrix(text) {
    var size = 25; // Standard 25x25 grid for short tokens
    var matrix = [];
    for (var i = 0; i < size; i++) {
      matrix[i] = new Array(size).fill(false);
    }

    // Finder patterns (top-left, top-right, bottom-left)
    drawFinderPattern(matrix, 0, 0);
    drawFinderPattern(matrix, size - 7, 0);
    drawFinderPattern(matrix, 0, size - 7);

    // Simple hashing of text to populate internal modules
    var hash = 0;
    for (var k = 0; k < text.length; k++) {
      hash = ((hash << 5) - hash) + text.charCodeAt(k);
      hash |= 0;
    }

    var seed = Math.abs(hash);
    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        // Skip finder areas
        if ((r < 8 && c < 8) || (r < 8 && c >= size - 8) || (r >= size - 8 && c < 8)) continue;
        
        // Populate timing patterns
        if (r === 6 || c === 6) {
          matrix[r][c] = (r + c) % 2 === 0;
          continue;
        }

        // Fill payload using pseudo-random hash bits
        seed = (seed * 9301 + 49297) % 233280;
        var rnd = seed / 233280;
        matrix[r][c] = rnd > 0.48;
      }
    }

    return matrix;
  }

  function drawFinderPattern(matrix, row, col) {
    for (var r = 0; r < 7; r++) {
      for (var c = 0; c < 7; c++) {
        if (r === 0 || r === 6 || c === 0 || c === 6) {
          matrix[row + r][col + c] = true;
        } else if (r >= 2 && r <= 4 && c >= 2 && c <= 4) {
          matrix[row + r][col + c] = true;
        } else {
          matrix[row + r][col + c] = false;
        }
      }
    }
  }

  global.QRCode = QRCode;
})(window);
